import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv includes header line', () => {
  const csv = exportCsv([]);

  assert(csv.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv ends with newline', () => {
  const csv = exportCsv([]);

  assert(csv.endsWith('\n'));
});

test('exportCsv with single invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes('Northwind Studio'));
  assert(csv.includes('2026-10-07'));
  assert(csv.includes('issued'));
});

test('exportCsv includes invoice number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes(r2.value.number));
});

test('exportCsv formats amounts with 2 decimals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);

  const csv = exportCsv([r2.value]);

  const euros = (totals.subtotal / 100).toFixed(2);
  assert(csv.includes(euros));
});

test('exportCsv uses dot as decimal separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.match(/\d+\.\d{2}/));
});

test('exportCsv without currency sign', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(!csv.includes('€'));
});

test('exportCsv without thousands separator', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(!csv.match(/\d{1,3},\d{3}/));
});

test('exportCsv with multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r1i = issueInvoice(r1.value, []);
  const r2i = issueInvoice(r2.value, []);

  const csv = exportCsv([r1i.value, r2i.value]);

  const lines = csv.trim().split('\n');
  assert.equal(lines.length, 3);
});

test('exportCsv with customer name containing comma', () => {
  const csv = exportCsv([
    {
      number: 'INV-2026-0001',
      customerId: 'C-006',
      issueDate: '2026-10-07',
      dueDate: '2026-11-07',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
    },
  ]);

  assert(csv.includes('Marlow "The Print Shop"'));
});

test('exportCsv escapes customer name with comma', () => {
  const csv = exportCsv([
    {
      number: 'INV-2026-0001',
      customerId: 'C-006',
      issueDate: '2026-10-07',
      dueDate: '2026-11-07',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
    },
  ]);

  assert(csv.includes('"Marlow ""The Print Shop"""'));
});

test('exportCsv includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);

  const csv = exportCsv([r2.value]);

  const dueLine = csv.split('\n')[1];
  const fields = dueLine.split(',');
  const lastField = fields[fields.length - 1];
  const expectedDue = (totals.total / 100).toFixed(2);
  assert.equal(lastField, expectedDue);
});

test('exportCsv with partially paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const r3 = recordPayment(r2.value, { amount: 1000, date: '2026-10-08' });

  const totals = invoiceTotals(r2.value);
  const csv = exportCsv([r3.value]);

  const expectedDue = ((totals.total - 1000) / 100).toFixed(2);
  assert(csv.includes(expectedDue));
});

test('exportCsv preserves invoice order', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r1i = issueInvoice(r1.value, []);
  const r2i = issueInvoice(r2.value, []);

  const csv = exportCsv([r1i.value, r2i.value]);

  const lines = csv.trim().split('\n');
  assert(lines[1].includes(r1i.value.number));
  assert(lines[2].includes(r2i.value.number));
});

test('exportCsv includes issueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes('2026-10-15'));
});

test('exportCsv includes dueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes('2026-10-21'));
});

test('exportCsv includes status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes('issued'));
});

test('exportCsv with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);

  const csv = exportCsv([r2.value]);

  const discountEuros = (totals.discount / 100).toFixed(2);
  assert(csv.includes(discountEuros));
  assert(csv.includes('850'));
});

test('exportCsv with VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);

  const csv = exportCsv([r2.value]);

  const vatEuros = (totals.vat / 100).toFixed(2);
  assert(csv.includes(vatEuros));
});

test('exportCsv with subtotal, discount, VAT, and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);

  const csv = exportCsv([r2.value]);

  const subtotalEuros = (totals.subtotal / 100).toFixed(2);
  const discountEuros = (totals.discount / 100).toFixed(2);
  const vatEuros = (totals.vat / 100).toFixed(2);
  const totalEuros = (totals.total / 100).toFixed(2);

  assert(csv.includes(subtotalEuros));
  assert(csv.includes(discountEuros));
  assert(csv.includes(vatEuros));
  assert(csv.includes(totalEuros));
});

test('exportCsv with large amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  assert(csv.includes('2450000'));
});

test('exportCsv line ending consistency', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  const lines = csv.split('\n');
  assert(lines.length >= 3);
  assert.equal(lines[lines.length - 1], '');
});

test('exportCsv header matches data columns', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);

  const csv = exportCsv([r2.value]);

  const lines = csv.trim().split('\n');
  const headerCols = lines[0].split(',').length;
  const dataCols = lines[1].split(',').length;

  assert.equal(headerCols, dataCols);
});

